int yam_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    int err = 0;
    void __user *user_data = ifr->ifr_data;

    if (!capable(CAP_NET_ADMIN))
        return -EPERM;

    if (dev->flags & IFF_RUNNING) {
        /* Prevent parameter changes while device is running */
        return -EBUSY;
    }

    switch (cmd) {
    case YAM_IOCTL_SET_BITRATE:
    {
        unsigned int bitrate;
        if (copy_from_user(&bitrate, user_data, sizeof(bitrate)))
            return -EFAULT;

        if (bitrate < MIN_BITRATE || bitrate > MAX_BITRATE)
            return -EINVAL;

        dev->bitrate = bitrate;
        break;
    }

    case YAM_IOCTL_GET_BITRATE:
    {
        if (!access_ok(VERIFY_WRITE, user_data, sizeof(unsigned int)))
            return -EFAULT;
        if (copy_to_user(user_data, &dev->bitrate, sizeof(unsigned int)))
            return -EFAULT;
        break;
    }

    case YAM_IOCTL_SET_BAUDRATE:
    {
        unsigned int baudrate;
        if (copy_from_user(&baudrate, user_data, sizeof(baudrate)))
            return -EFAULT;

        if (baudrate < MIN_BAUDRATE || baudrate > MAX_BAUDRATE)
            return -EINVAL;

        dev->baudrate = baudrate;
        break;
    }

    case YAM_IOCTL_GET_BAUDRATE:
    {
        if (!access_ok(VERIFY_WRITE, user_data, sizeof(unsigned int)))
            return -EFAULT;
        if (copy_to_user(user_data, &dev->baudrate, sizeof(unsigned int)))
            return -EFAULT;
        break;
    }

    case YAM_IOCTL_SET_IRQ:
    {
        unsigned int irq;
        if (copy_from_user(&irq, user_data, sizeof(irq)))
            return -EFAULT;

        if (irq < MIN_IRQ || irq > MAX_IRQ)
            return -EINVAL;

        dev->irq = irq;
        break;
    }

    default:
        err = -EINVAL;
        break;
    }

    return err;
}

int yam_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    int *addr;
    int i;

    if (!capable(CAP_NET_ADMIN))
        return -EPERM;

    if (!netif_running(dev) && (cmd != SIOCDEVPRIVATE + 1)) {
        if (copy_from_user(&i, ifr->ifr_data, sizeof(int)))
            return -EFAULT;
        if (i == 0)
            return 0;
    }

    if (cmd == SIOCDEVPRIVATE) {
        if ((addr = kmalloc(4, GFP_KERNEL)) == NULL)
            return -ENOMEM;
        if (copy_from_user(addr, ifr->ifr_data, 4)) {
            kfree(addr);
            return -EFAULT;
        }
        if (copy_to_user(ifr->ifr_data, addr, 4)) {
            kfree(addr);
            return -EFAULT;
        }
        kfree(addr);
        return 0;
    }

    if (cmd == SIOCDEVPRIVATE + 1) {
        if (copy_from_user(&i, ifr->ifr_data, sizeof(int)))
            return -EFAULT;
        if (i == 0)
            return 0;
        return -EINVAL;
    }

    return -EOPNOTSUPP;
}

