    switch (cmd) {
    case SIOCYAMSET:
    case SIOCYAMGET:
        if (copy_from_user(&i, ifr->ifr_data, sizeof(unsigned int)))
            return -EFAULT;

        if (cmd == SIOCYAMSET) {
            if (dev->flags & IFF_RUNNING)
                return -EBUSY;

            /* Perform configuration based on i */
        }

