            return -EFAULT;

        break;
    default:
        return -EINVAL;
    }

    return 0;
}

int yam_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    int ret = 0;
    unsigned long flags;

    if (!dev || !ifr)
        return -EINVAL;

    if (dev->flags & IFF_RUNNING) {
        switch (cmd) {
        case YAM_SET_BITRATE:
        case YAM_SET_BAUDRATE:
        case YAM_SET_IRQ:
            return -EBUSY; /* Can't modify these while device is running */
        }
    }

    switch (cmd) {
    case YAM_GET_BITRATE:
    {
        unsigned int bitrate;
        struct ifreq local_ifr;

        if (copy_from_user(&local_ifr, ifr, sizeof(local_ifr)))
            return -EFAULT;

        bitrate = dev->bitrate;
        if (copy_to_user(local_ifr.ifr_data, &bitrate, sizeof(bitrate)))
            return -EFAULT;

        if (copy_to_user(ifr, &local_ifr, sizeof(local_ifr)))
            return -EFAULT;

        break;
    }

    case YAM_SET_BITRATE:
    {
        unsigned int new_bitrate;

        if (copy_from_user(&new_bitrate, ifr->ifr_data, sizeof(new_bitrate)))
            return -EFAULT;

        if (new_bitrate < MIN_BITRATE || new_bitrate > MAX_BITRATE)
            return -EINVAL;

        dev->bitrate = new_bitrate;
        break;
    }

    case YAM_GET_BAUDRATE:
    {
        unsigned int baudrate;
        struct ifreq local_ifr;

        if (copy_from_user(&local_ifr, ifr, sizeof(local_ifr)))
            return -EFAULT;

        baudrate = dev->baudrate;
        if (copy_to_user(local_ifr.ifr_data, &baudrate, sizeof(baudrate)))
            return -EFAULT;

        if (copy_to_user(ifr, &local_ifr, sizeof(local_ifr)))
            return -EFAULT;

        break;
    }

    case YAM_SET_BAUDRATE:
    {
        unsigned int new_baudrate;

        if (copy_from_user(&new_baudrate, ifr->ifr_data, sizeof(new_baudrate)))
            return -EFAULT;

        if (new_baudrate < MIN_BAUDRATE || new_baudrate > MAX_BAUDRATE)
            return -EINVAL;

        dev->baudrate = new_baudrate;
        break;
    }

    case YAM_GET_IRQ:
    {
        int irq;
        struct ifreq local_ifr;

        if (copy_from_user(&local_ifr, ifr, sizeof(local_ifr)))
            return -EFAULT;

        irq = dev->irq;
        if (copy_to_user(local_ifr.ifr_data, &irq, sizeof(irq)))
            return -EFAULT;

        if (copy_to_user(ifr, &local_ifr, sizeof(local_ifr)))
            return -EFAULT;

        break;
    }

    case YAM_SET_IRQ:
    {
        int new_irq;

        if (copy_from_user(&new_irq, ifr->ifr_data, sizeof(new_irq)))
            return -EFAULT;

        if (new_irq < 0 || new_irq >= NR_IRQS)
            return -EINVAL;

        dev->irq = new_irq;
        break;
    }

    default:
        ret = -EINVAL;
    }

    return ret;
}

#include <linux/netdevice.h>
#include <linux/if.h>
#include <linux/uaccess.h>

int yam_ioctl(struct net_device *dev, struct ifreq *ifr, int cmd)
{
    int err = 0;

    if (!netif_device_present(dev))
        return -ENODEV;

    if (dev->flags & IFF_RUNNING) {
        /* Prevent changes to certain parameters when the device is running */
        if (cmd == SIOCYAMSETBITRATE || cmd == SIOCYAMSETBAUDRATE || cmd == SIOCYAMSETIRQ) {
            return -EBUSY;
        }
    }

    if (copy_from_user(&dev->priv, ifr->ifr_data, sizeof(struct yam_config)))
        return -EFAULT;

    switch (cmd) {
    case SIOCGYAMBITRATE:
        if (copy_to_user(ifr->ifr_data, &dev->priv.bitrate, sizeof(int)))
            err = -EFAULT;
        break;
    case SIOCGYAMBAUDRATE:
        if (copy_to_user(ifr->ifr_data, &dev->priv.baudrate, sizeof(int)))
            err = -EFAULT;
        break;
    case SIOCGYAMIRQ:
        if (copy_to_user(ifr->ifr_data, &dev->priv.irq, sizeof(int)))
            err = -EFAULT;
        break;
    case SIOCYAMSETBITRATE:
        dev->priv.bitrate = ((struct yam_config *)ifr->ifr_data)->bitrate;
        break;
    case SIOCYAMSETBAUDRATE:
        dev->priv.baudrate = ((struct yam_config *)ifr->ifr_data)->baudrate;
        break;
    case SIOCYAMSETIRQ:
        dev->priv.irq = ((struct yam_config *)ifr->ifr_data)->irq;
        break;
    default:
        err = -EINVAL;
        break;
    }

    return err;
}
